CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE institutions(id uuid PRIMARY KEY, name text NOT NULL);
CREATE TABLE units(id uuid PRIMARY KEY, institution_id uuid NOT NULL REFERENCES institutions(id), name text NOT NULL, timezone text NOT NULL DEFAULT 'America/Sao_Paulo', active boolean NOT NULL DEFAULT true, UNIQUE(institution_id,name));
CREATE TABLE sectors(id uuid PRIMARY KEY, unit_id uuid NOT NULL REFERENCES units(id), name text NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(unit_id,name));
CREATE TABLE roles(id text PRIMARY KEY, name text NOT NULL, permissions text[] NOT NULL);
CREATE TABLE users(id uuid PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, role_id text NOT NULL REFERENCES roles(id), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_units(user_id uuid NOT NULL REFERENCES users(id), unit_id uuid NOT NULL REFERENCES units(id), PRIMARY KEY(user_id,unit_id));
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE login_attempts(key text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, until_at timestamptz NOT NULL);
CREATE TABLE used_totp(user_id uuid NOT NULL REFERENCES users(id), step bigint NOT NULL, PRIMARY KEY(user_id,step));
CREATE TABLE patients(id uuid PRIMARY KEY, unit_id uuid NOT NULL REFERENCES units(id), name text NOT NULL CHECK(length(name) BETWEEN 3 AND 160), social_name text NOT NULL DEFAULT '', birth_date date, provisional boolean NOT NULL DEFAULT false, cpf text, cns text, phone text NOT NULL DEFAULT '', mother_name text NOT NULL DEFAULT '', emergency_contact text NOT NULL DEFAULT '', accessibility text NOT NULL DEFAULT '', version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(provisional OR birth_date IS NOT NULL), CHECK(cpf IS NULL OR cpf ~ '^[0-9]{11}$'), CHECK(cns IS NULL OR cns ~ '^[0-9]{15}$'), UNIQUE(unit_id,cpf), UNIQUE(unit_id,cns));
CREATE INDEX patients_search ON patients(unit_id,lower(name));
CREATE INDEX patients_created ON patients(unit_id,created_at DESC);
CREATE TABLE settings(unit_id uuid PRIMARY KEY REFERENCES units(id), services text[] NOT NULL DEFAULT ARRAY['recepcao'], version integer NOT NULL DEFAULT 1);
CREATE TABLE preferences(user_id uuid PRIMARY KEY REFERENCES users(id), value jsonb NOT NULL DEFAULT '{}');
CREATE TABLE idempotency(user_id uuid NOT NULL REFERENCES users(id), key text NOT NULL, request_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,key));
CREATE TABLE audit(id bigserial PRIMARY KEY, user_id uuid REFERENCES users(id), role_id text, unit_id uuid REFERENCES units(id), action text NOT NULL, resource text NOT NULL, result text NOT NULL, reason text, correlation_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), previous_hash text NOT NULL, hash text NOT NULL);
CREATE INDEX audit_unit_date ON audit(unit_id,created_at DESC);
CREATE FUNCTION protect_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit is append only'; END $$;
CREATE TRIGGER audit_no_change BEFORE UPDATE OR DELETE ON audit FOR EACH ROW EXECUTE FUNCTION protect_audit();
INSERT INTO schema_migrations(version) VALUES(1);
